/*
ERPNext Web Page CSS
LIFE green + white theme, adapted from your reference dashboard.
*/

.navbar { display: none; }
.web-footer { display: none; }

.tt-block,
.tt-block * {
  box-sizing: border-box;
}

.tt-block {
  width: 100%;
  margin: 0 auto;
  padding: 18px;
  color: #152418;
  font-family: "Inter", "Segoe UI", Arial, system-ui, sans-serif;
  font-size: 12px;
  line-height: 1.45;
  background: #F3FAF4;
  border: 1px solid #DCE9DE;
  border-radius: 14px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.06),
    0 8px 26px rgba(15, 61, 30, 0.09);
}

/* ============================================================
   TABS
   ============================================================ */

.tt-tabs {
  display: flex;
  gap: 6px;
  margin: -18px -18px 18px;
  padding: 10px 16px 0;
  overflow-x: auto;
  background: #FFFFFF;
  border-bottom: 1px solid #DCE9DE;
  border-radius: 14px 14px 0 0;
}

.tt-tab-btn {
  min-height: 40px;
  padding: 0 15px;
  color: #5F6F63;
  font-family: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: transparent;
  border: 1px solid transparent;
  border-bottom: 3px solid transparent;
  border-radius: 9px 9px 0 0;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease;
}

.tt-tab-btn:hover {
  color: #14501F;
  background: #F3FAF4;
}

.tt-tab-btn.active {
  color: #14501F;
  background: #E8F5E9;
  border-color: #DCE9DE;
  border-bottom-color: #2E7D32;
}

/* ============================================================
   PANEL / HEADER / FILTERS
   ============================================================ */

.tt-panel {
  padding: 16px;
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 14px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.05),
    0 5px 16px rgba(15, 61, 30, 0.07);
}

.tt-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
  padding-bottom: 12px;
  border-bottom: 1px dashed #CFE1D2;
}

.tt-header h3 {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  color: #0F3D1E;
  font-size: 17px;
  font-weight: 900;
  line-height: 1.3;
}

.tt-badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 3px 10px;
  color: #FFFFFF;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.25px;
  background: #1B5E20;
  border: 1px solid #1B5E20;
  border-radius: 999px;
  box-shadow: 0 2px 6px rgba(27, 94, 32, 0.18);
}

.pkg-badge {
  background: #2E7D32;
  border-color: #2E7D32;
}

.lr-badge {
  color: #5D3A00;
  background: #FFF3CD;
  border-color: #F1D78A;
  box-shadow: none;
}

.tt-filter-row {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

.tt-search,
.pkg-search,
.lr-search {
  width: 250px;
  max-width: 100%;
  height: 36px;
  padding: 0 13px;
  color: #152418;
  font-family: inherit;
  font-size: 11.5px;
  background: #FFFFFF;
  border: 1.5px solid #CFE1D2;
  border-radius: 999px;
  outline: none;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    background 0.15s ease;
}

.tt-search::placeholder,
.pkg-search::placeholder,
.lr-search::placeholder {
  color: #87968B;
}

.tt-search:hover,
.pkg-search:hover,
.lr-search:hover {
  border-color: #A5D6A7;
}

.tt-search:focus,
.pkg-search:focus,
.lr-search:focus {
  background: #FFFFFF;
  border-color: #43A047;
  box-shadow: 0 0 0 3px rgba(67, 160, 71, 0.12);
}

.tt-offer-filter-btn {
  height: 36px;
  padding: 0 14px;
  color: #14501F;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: #FFFFFF;
  border: 1.5px solid #A5D6A7;
  border-radius: 999px;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.tt-offer-filter-btn:hover {
  color: #0F3D1E;
  background: #E8F5E9;
  border-color: #66BB6A;
  box-shadow: 0 0 0 3px rgba(67, 160, 71, 0.10);
  transform: translateY(-1px);
}

.tt-offer-filter-btn.active {
  color: #FFFFFF;
  background: #1B5E20;
  border-color: #1B5E20;
  box-shadow: 0 3px 9px rgba(27, 94, 32, 0.22);
}

/* ============================================================
   TABLE
   ============================================================ */

.tt-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #DCE9DE;
  border-radius: 11px;
}

.tt-table {
  width: 100%;
  min-width: 760px;
  border-collapse: separate;
  border-spacing: 0;
  color: #152418;
  font-size: 11.5px;
  background: #FFFFFF;
}

.tt-table thead tr {
  color: #FFFFFF;
  text-align: left;
  background: #1B5E20;
}

.tt-table th {
  padding: 10px 12px;
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.25px;
  white-space: nowrap;
  border-bottom: 1px solid #14501F;
}

.tt-table td {
  padding: 10px 12px;
  vertical-align: middle;
  border-bottom: 1px solid #EEF4EF;
}

.tt-table tbody tr:last-child td {
  border-bottom: 0;
}

.tt-row-even { background: #F8FCF8; }
.tt-row-odd  { background: #FFFFFF; }

.tt-table tbody tr:hover td {
  background: #EEF8EF;
}

.tt-name {
  color: #0F3D1E;
  font-weight: 800;
}

.tt-name-main {
  font-weight: 700;
  color: #152418;
  line-height: 1.35;
}

.tt-name-category {
  margin-top: 2px;
  font-size: 11px;
  font-weight: 500;
  color: #6f7f72;
  line-height: 1.25;
}

/* ============================================================
   PILLS / STATUS
   ============================================================ */

.tt-pill {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 3px 9px;
  font-size: 10.5px;
  font-weight: 800;
  white-space: nowrap;
  border-radius: 999px;
}

.tt-pill-rate {
  color: #14501F;
  background: #E8F5E9;
  border: 1px solid #C8E6C9;
}

.tt-pill-min {
  color: #7A5200;
  background: #FFF8E1;
  border: 1px solid #F3DE9B;
}

.tt-pill-max {
  color: #8F1D1D;
  background: #FDECEA;
  border: 1px solid #F2B8B5;
}

.tt-pill-offer-yes,
.pkg-pill-active {
  color: #14501F;
  background: #E8F5E9;
  border: 1px solid #C8E6C9;
}

.tt-pill-offer-no,
.pkg-pill-inactive {
  color: #637668;
  background: #EEF4EF;
  border: 1px solid #D7E4D9;
}

.tt-loading {
  padding: 22px !important;
  color: #5F6F63;
  font-weight: 600;
  text-align: center;
}

/* ============================================================
   PAGINATION / ACTIONS
   ============================================================ */

.tt-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 14px;
}

.tt-pagination button,
.pkg-view-btn {
  min-height: 32px;
  padding: 0 14px;
  color: #FFFFFF;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: #1B5E20;
  border: 1px solid #1B5E20;
  border-radius: 999px;
  box-shadow: 0 3px 9px rgba(27, 94, 32, 0.18);
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease,
    opacity 0.15s ease;
}

.tt-pagination button:hover:not(:disabled),
.pkg-view-btn:hover {
  background: #2E7D32;
  border-color: #2E7D32;
  box-shadow: 0 5px 12px rgba(27, 94, 32, 0.24);
  transform: translateY(-1px);
}

.tt-pagination button:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.tt-page-info,
.pkg-page-info,
.lr-page-info {
  color: #5F6F63;
  font-size: 10.5px;
  font-weight: 700;
}

/* ============================================================
   PACKAGE DETAIL MODAL
   ============================================================ */

.pkg-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 61, 30, 0.46);
  backdrop-filter: blur(2px);
}

.pkg-modal {
  width: min(680px, 96vw);
  max-height: 86vh;
  overflow-y: auto;
  background: #FFFFFF;
  border: 1px solid #CFE1D2;
  border-radius: 14px;
  box-shadow: 0 18px 55px rgba(15, 61, 30, 0.28);
}

.pkg-modal-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 18px;
  color: #FFFFFF;
  background: #1B5E20;
  border-bottom: 1px solid #14501F;
  border-radius: 13px 13px 0 0;
}

.pkg-modal-title {
  margin: 0;
  color: #FFFFFF;
  font-size: 14px;
  font-weight: 900;
}

.pkg-modal-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  color: #E8F5E9;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 50%;
}

.pkg-modal-close:hover {
  color: #FFFFFF;
  background: rgba(255, 255, 255, 0.18);
}

.pkg-modal-body {
  padding: 18px;
  overflow-x: auto;
  background: #FFFFFF;
}

.pkg-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px 14px;
}

.pkg-detail-grid > div {
  min-width: 0;
  padding: 10px 11px;
  background: #F8FCF8;
  border: 1px solid #E2EEE4;
  border-radius: 9px;
}

.pkg-detail-grid > div div {
  margin-top: 3px;
  color: #152418;
  font-size: 11.5px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.pkg-detail-label {
  display: inline-block;
  color: #35633D;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 0.75px;
  text-transform: uppercase;
}

.pkg-desc {
  margin-top: 14px;
  padding: 11px 12px;
  color: #152418;
  background: #F8FCF8;
  border: 1px solid #E2EEE4;
  border-radius: 9px;
}

.pkg-desc > div {
  margin-top: 4px;
  color: #2D4332;
  font-size: 11.5px;
  font-weight: 500;
  line-height: 1.55;
}

.pkg-modal-body > .tt-table {
  min-width: 600px;
  margin-top: 6px;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 768px) {
  .tt-block {
    padding: 12px;
    border-radius: 10px;
  }

  .tt-tabs {
    margin: -12px -12px 14px;
    padding: 8px 10px 0;
    border-radius: 10px 10px 0 0;
  }

  .tt-panel {
    padding: 12px;
    border-radius: 10px;
  }

  .tt-header {
    align-items: stretch;
  }

  .tt-header h3 {
    width: 100%;
    font-size: 15px;
  }

  .tt-filter-row,
  .tt-search,
  .pkg-search,
  .lr-search {
    width: 100%;
  }

  .tt-offer-filter-btn {
    flex: 1 1 auto;
  }

  .pkg-detail-grid {
    grid-template-columns: 1fr;
  }

  .pkg-modal-overlay {
    padding: 10px;
  }

  .pkg-modal {
    width: 100%;
    max-height: 92vh;
  }
}

