/*
ERPNext Web Page JavaScript
Converted from the Custom HTML Block version.

Key Web Page changes:
- Scopes all selectors to .tt-block instead of Custom HTML Block root_element.
- Waits until both the page DOM and Frappe are available.
- Prevents duplicate initialization if ERPNext re-renders the page content.
*/
(function () {
  'use strict';

  var TT_INIT_RETRIES = 0;
  var TT_MAX_INIT_RETRIES = 100;

  function initTherapyPricingWebPage() {
    var R = document.querySelector('.tt-block');

    if (!R) {
      if (TT_INIT_RETRIES < TT_MAX_INIT_RETRIES) {
        TT_INIT_RETRIES += 1;
        setTimeout(initTherapyPricingWebPage, 100);
      }
      return;
    }

    if (R.__therapyPricingWebPageInitialized) {
      return;
    }

    if (typeof window.frappe === 'undefined') {
      if (TT_INIT_RETRIES < TT_MAX_INIT_RETRIES) {
        TT_INIT_RETRIES += 1;
        setTimeout(initTherapyPricingWebPage, 100);
      }
      return;
    }

    R.__therapyPricingWebPageInitialized = true;

    let allRows = [];
    let filteredRows = [];
    let currentPage = 1;
    const pageSize = 10;

    let searchInput = R.querySelector('.tt-search');
    let offerFilterBtn = R.querySelector('.tt-offer-filter-btn');
    let offerOnly = false;

    let tbody = R.querySelector('.tt-tbody');
    let prevBtn = R.querySelector('.tt-prev');
    let nextBtn = R.querySelector('.tt-next');
    let pageInfo = R.querySelector('.tt-page-info');

    function fmtMoney(v) {
      return (v !== null && v !== undefined && v !== '') ? Number(v).toFixed(2) : '-';
    }
    function fmtDate(d) {
      if (!d) return '-';
      let p = d.split('-');
      return p.length === 3 ? (p[2] + '/' + p[1] + '/' + p[0]) : d;
    }

    // Healthcare Service Unit is used as the Therapy Type category.
    // Example: "Hair - LSACPL" -> "Hair".
    function cleanCategory(value) {
      return String(value || '')
        .replace(/\s*-\s*LSACPL\s*$/i, '')
        .trim();
    }

    function escHtml(value) {
      return String(value == null ? '' : value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function renderPage() {
      let totalPages = Math.max(1, Math.ceil(filteredRows.length / pageSize));
      if (currentPage > totalPages) currentPage = totalPages;
      if (currentPage < 1) currentPage = 1;

      let start = (currentPage - 1) * pageSize;
      let pageRows = filteredRows.slice(start, start + pageSize);

      if (!pageRows.length) {
        tbody.innerHTML = '<tr><td colspan="5" class="tt-loading">No results found</td></tr>';
      } else {
        tbody.innerHTML = pageRows.map(function(r, i) {
          let cls = (i % 2 === 0) ? 'tt-row-even' : 'tt-row-odd';
          let offerHtml = r.offer_applied
            ? '<span class="tt-pill tt-pill-offer-yes">✅ ' + r.offer_rate.toFixed(2) + '</span>'
            : '<span class="tt-pill tt-pill-offer-no">— No</span>';
          let category = cleanCategory(r.healthcare_service_unit);
          let therapyNameHtml =
            '<div class="tt-name-main">' + escHtml(r.therapy_type || '') + '</div>' +
            (category ? '<div class="tt-name-category">' + escHtml(category) + '</div>' : '');

          return '<tr class="' + cls + '">' +
            '<td class="tt-name">' + therapyNameHtml + '</td>' +
            '<td><span class="tt-pill tt-pill-rate">' + (r.rate != null ? r.rate.toFixed(2) : '-') + '</span></td>' +
            '<td><span class="tt-pill tt-pill-min">' + (r.minimum_price != null ? r.minimum_price.toFixed(2) : '-') + '</span></td>' +
            '<td><span class="tt-pill tt-pill-max">' + (r.maximum_price != null ? r.maximum_price.toFixed(2) : '-') + '</span></td>' +
            '<td>' + offerHtml + '</td>' +
          '</tr>';
        }).join('');
      }

      pageInfo.textContent = 'Page ' + currentPage + ' of ' + totalPages + ' (' + filteredRows.length + ' items)';
      prevBtn.disabled = currentPage <= 1;
      nextBtn.disabled = currentPage >= totalPages;
    }

    function applyFilter() {
      let q = searchInput.value.toLowerCase();

      filteredRows = allRows.filter(function(r) {
        let therapyName = (r.therapy_type || '').toLowerCase();
        let category = cleanCategory(r.healthcare_service_unit).toLowerCase();
        let matchesSearch = therapyName.indexOf(q) !== -1 || category.indexOf(q) !== -1;
        let matchesOffer = !offerOnly || r.offer_applied === true;

        return matchesSearch && matchesOffer;
      });

      currentPage = 1;
      renderPage();
    }

    searchInput.addEventListener('input', applyFilter);
    offerFilterBtn.addEventListener('click', function() {
      offerOnly = !offerOnly;

      offerFilterBtn.classList.toggle('active', offerOnly);
      offerFilterBtn.setAttribute('data-active', offerOnly ? '1' : '0');
      offerFilterBtn.innerHTML = offerOnly ? '✅ Offer Applied Only' : '🏷️ Offer Applied';

      applyFilter();
    });

    prevBtn.addEventListener('click', function() { currentPage--; renderPage(); });
    nextBtn.addEventListener('click', function() { currentPage++; renderPage(); });

    function load() {
      tbody.innerHTML = '<tr><td colspan="5" class="tt-loading">Loading therapy types and current offers…</td></tr>';
      frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Therapy Type',
          filters: { is_billable: 1 },
          fields: ['therapy_type', 'healthcare_service_unit', 'item_code', 'rate', 'minimum_price', 'maximum_price'],
          order_by: 'therapy_type asc',
          limit_page_length: 0
        },
        callback: function(response) {
          let baseRows = (response.message || []).filter(function(row) {
            return row.rate && row.rate !== 0;
          });
          finish({});
          window.dispatchEvent(new Event('life-portal:primary-ready'));
          loadPricingRules(baseRows);
        },
        error: function() {
          tbody.innerHTML = '<tr><td colspan="5" class="tt-loading" style="color:#e74c3c;">Failed to load therapy types</td></tr>';
          window.dispatchEvent(new Event('life-portal:primary-ready'));
        }
      });
    }

    function loadPricingRules(baseRows) {
      let today = (frappe.datetime && frappe.datetime.get_today)
        ? frappe.datetime.get_today()
        : new Date().toISOString().slice(0, 10);

      function finish(offerMap) {
        allRows = baseRows.map(function(row) {
          let offer = row.item_code ? offerMap[row.item_code] : null;
          if (offer) {
            row.offer_applied = true;
            row.offer_rule = offer.rule_name;
            let base = row.rate || 0;
            let finalRate = base;
            if (offer.discount_percentage) { finalRate = base - (base * offer.discount_percentage / 100); }
            else if (offer.discount_amount) { finalRate = base - offer.discount_amount; }
            else if (offer.rate) { finalRate = offer.rate; }
            if (finalRate < 0) finalRate = 0;
            row.offer_rate = finalRate;
          } else {
            row.offer_applied = false;
            row.offer_rate = null;
            row.offer_rule = null;
          }
          return row;
        });
        applyFilter();
      }

      // Offer data is supplemental; the main table already rendered.
      frappe.call({
        method: 'frappe.client.get_list',
        silent: true,
        args: {
          doctype: 'Pricing Rule',
          filters: { disable: 0 },
          fields: ['name'],
          limit_page_length: 0
        },
        callback: function(response) {
          let names = (response.message || []).map(function(rule) { return rule.name; });
          if (!names.length) return;
          let offerMap = {};
          let remaining = names.length;
          let nextRule = 0;
          function readNextRule() {
            if (nextRule >= names.length) return;
            let name = names[nextRule++];
            frappe.call({
              method: 'frappe.client.get',
              silent: true,
              args: { doctype: 'Pricing Rule', name: name },
              callback: function(ruleResponse) {
                let doc = ruleResponse.message;
                if (doc && doc.items) {
                  let from = doc.valid_from;
                  let upto = doc.valid_upto;
                  if ((!from || today >= from) && (!upto || today <= upto)) {
                    doc.items.forEach(function(item) {
                      if (item.item_code) {
                        offerMap[item.item_code] = {
                          discount_percentage: doc.discount_percentage,
                          discount_amount: doc.discount_amount,
                          rate: doc.rate,
                          rule_name: doc.name
                        };
                      }
                    });
                  }
                }
                remaining--;
                if (remaining === 0) finish(offerMap);
                else readNextRule();
              },
              error: function() {
                remaining--;
                if (remaining === 0) finish(offerMap);
                else readNextRule();
              }
            });
          }
          for (let i = 0; i < Math.min(4, names.length); i++) readNextRule();
        },
        error: function() { /* Main prices are already visible. */ }
      });
    }

    load();

    /* ===================== TAB SWITCHING ===================== */
    let tabBtns = R.querySelectorAll('.tt-tab-btn');
    let panels = R.querySelectorAll('.tt-panel');
    tabBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        tabBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        let tab = btn.getAttribute('data-tab');
        panels.forEach(function(p) {
          p.style.display = (p.getAttribute('data-panel') === tab) ? '' : 'none';
        });
        if (tab === 'packages' && !pkgLoaded) { loadPackages(); }
        if (tab === 'liferise' && !lrLoaded) { loadLifeRise(); }
      });
    });

    /* ===================== PACKAGES TAB ===================== */
    let pkgAllRows = [];
    let pkgFilteredRows = [];
    let pkgCurrentPage = 1;
    const pkgPageSize = 10;
    let pkgLoaded = false;

    let pkgSearchInput = R.querySelector('.pkg-search');
    let pkgTbody = R.querySelector('.pkg-tbody');
    let pkgPrevBtn = R.querySelector('.pkg-prev');
    let pkgNextBtn = R.querySelector('.pkg-next');
    let pkgPageInfo = R.querySelector('.pkg-page-info');
    let modalOverlay = R.querySelector('.pkg-modal-overlay');
    let modalTitle = R.querySelector('.pkg-modal-title');
    let modalBody = R.querySelector('.pkg-modal-body');
    let modalClose = R.querySelector('.pkg-modal-close');

    function pkgRenderPage() {
      let totalPages = Math.max(1, Math.ceil(pkgFilteredRows.length / pkgPageSize));
      if (pkgCurrentPage > totalPages) pkgCurrentPage = totalPages;
      if (pkgCurrentPage < 1) pkgCurrentPage = 1;
      let start = (pkgCurrentPage - 1) * pkgPageSize;
      let pageRows = pkgFilteredRows.slice(start, start + pkgPageSize);

      if (!pageRows.length) {
        pkgTbody.innerHTML = '<tr><td colspan="8" class="tt-loading">No results found</td></tr>';
      } else {
        pkgTbody.innerHTML = pageRows.map(function(r, i) {
          let cls = (i % 2 === 0) ? 'tt-row-even' : 'tt-row-odd';
          let statusHtml = r.is_active
            ? '<span class="tt-pill pkg-pill-active">Active</span>'
            : '<span class="tt-pill pkg-pill-inactive">Inactive</span>';
          return '<tr class="' + cls + '">' +
            '<td class="tt-name">' + (r.plan_name || '') + '</td>' +
            '<td>' + (r.item_code || '-') + '</td>' +
            '<td><span class="tt-pill tt-pill-rate">' + (r.total_sessions != null ? r.total_sessions : '-') + '</span></td>' +
            '<td><span class="tt-pill tt-pill-max">' + fmtMoney(r.total_amount) + '</span></td>' +
            '<td><span class="tt-pill tt-pill-min">' + fmtMoney(r.offer_price) + '</span></td>' +
            '<td>' + fmtMoney(r.custom_including_gst) + '</td>' +
            '<td>' + statusHtml + '</td>' +
            '<td><button class="pkg-view-btn" data-name="' + String(r.name).replace(/"/g, '&quot;') + '">View</button></td>' +
          '</tr>';
        }).join('');
      }

      pkgPageInfo.textContent = 'Page ' + pkgCurrentPage + ' of ' + totalPages + ' (' + pkgFilteredRows.length + ' packages)';
      pkgPrevBtn.disabled = pkgCurrentPage <= 1;
      pkgNextBtn.disabled = pkgCurrentPage >= totalPages;

      pkgTbody.querySelectorAll('.pkg-view-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          openPkgModal(btn.getAttribute('data-name'));
        });
      });
    }

    function pkgApplyFilter() {
      let q = pkgSearchInput.value.toLowerCase();
      pkgFilteredRows = pkgAllRows.filter(function(r) {
        return (r.plan_name || '').toLowerCase().indexOf(q) !== -1 ||
               (r.item_code || '').toLowerCase().indexOf(q) !== -1;
      });
      pkgCurrentPage = 1;
      pkgRenderPage();
    }

    pkgSearchInput.addEventListener('input', pkgApplyFilter);
    pkgPrevBtn.addEventListener('click', function() { pkgCurrentPage--; pkgRenderPage(); });
    pkgNextBtn.addEventListener('click', function() { pkgCurrentPage++; pkgRenderPage(); });

    function loadPackages() {
      pkgTbody.innerHTML = '<tr><td colspan="8" class="tt-loading">Loading...</td></tr>';
      frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Therapy Plan Template',
          filters: { is_active: 1, plan_name: ['not like', '%LIFErise%'] },
          fields: ['name', 'plan_name', 'item_code', 'item_group', 'gst_hsn_code', 'description',
                   'total_sessions', 'total_amount', 'offer_price', 'custom_including_gst',
                   'is_active', 'offer_valid_from', 'offer_valid_to'],
          order_by: 'plan_name asc',
          limit_page_length: 0
        },
        callback: function(r) {
          pkgAllRows = r.message || [];
          pkgLoaded = true;
          pkgApplyFilter();
        },
        error: function() {
          pkgTbody.innerHTML = '<tr><td colspan="8" class="tt-loading" style="color:#e74c3c;">Failed to load packages</td></tr>';
        }
      });
    }

    function openPkgModal(name) {
      modalTitle.textContent = name;
      modalBody.innerHTML = '<div class="tt-loading">Loading details...</div>';
      modalOverlay.style.display = 'flex';

      frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Therapy Plan Template', name: name },
        callback: function(r) {
          let doc = r.message;
          if (!doc) {
            modalBody.innerHTML = '<div class="tt-loading" style="color:#e74c3c;">Not found</div>';
            return;
          }
          let rowsHtml = (doc.therapy_types || []).map(function(t, i) {
            let cls = (i % 2 === 0) ? 'tt-row-even' : 'tt-row-odd';
            return '<tr class="' + cls + '">' +
              '<td>' + (t.therapy_type || '') + '</td>' +
              '<td>' + (t.no_of_sessions != null ? t.no_of_sessions : '-') + '</td>' +
              '<td>' + fmtMoney(t.rate) + '</td>' +
              '<td>' + fmtMoney(t.amount) + '</td>' +
            '</tr>';
          }).join('');

          modalBody.innerHTML =
            '<div class="pkg-detail-grid">' +
              '<div><span class="pkg-detail-label">Item Code</span><div>' + (doc.item_code || '-') + '</div></div>' +
              '<div><span class="pkg-detail-label">Item Group</span><div>' + (doc.item_group || '-') + '</div></div>' +
              '<div><span class="pkg-detail-label">HSN/SAC</span><div>' + (doc.gst_hsn_code || '-') + '</div></div>' +
              '<div><span class="pkg-detail-label">Status</span><div>' + (doc.is_active ? 'Active' : 'Inactive') + '</div></div>' +
              '<div><span class="pkg-detail-label">Total Sessions</span><div>' + (doc.total_sessions != null ? doc.total_sessions : '-') + '</div></div>' +
              '<div><span class="pkg-detail-label">Total Amount</span><div>' + fmtMoney(doc.total_amount) + '</div></div>' +
              '<div><span class="pkg-detail-label">Offer Price</span><div>' + fmtMoney(doc.offer_price) + '</div></div>' +
              '<div><span class="pkg-detail-label">Incl. GST</span><div>' + fmtMoney(doc.custom_including_gst) + '</div></div>' +
              '<div><span class="pkg-detail-label">Offer Valid From</span><div>' + fmtDate(doc.offer_valid_from) + '</div></div>' +
              '<div><span class="pkg-detail-label">Offer Valid To</span><div>' + fmtDate(doc.offer_valid_to) + '</div></div>' +
            '</div>' +
            (doc.description ? '<div class="pkg-desc"><span class="pkg-detail-label">Description</span><div>' + doc.description + '</div></div>' : '') +
            '<div class="pkg-detail-label" style="margin-top:14px;display:block;">Included Therapy Types</div>' +
            '<table class="tt-table" style="margin-top:6px;">' +
              '<thead><tr><th>Therapy Type</th><th>Sessions</th><th>Rate</th><th>Amount</th></tr></thead>' +
              '<tbody>' + (rowsHtml || '<tr><td colspan="4" class="tt-loading">No therapy types</td></tr>') + '</tbody>' +
            '</table>';
        },
        error: function() {
          modalBody.innerHTML = '<div class="tt-loading" style="color:#e74c3c;">Failed to load details</div>';
        }
      });
    }

    modalClose.addEventListener('click', function() { modalOverlay.style.display = 'none'; });
    modalOverlay.addEventListener('click', function(e) {
      if (e.target === modalOverlay) modalOverlay.style.display = 'none';
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && modalOverlay.style.display !== 'none') {
        modalOverlay.style.display = 'none';
      }
    });

